import { describe, expect, it } from "vitest";
import { quote } from "./claim-office.js";

/**
 * Test list for the MHPCO Claim Office kata.
 *
 * Readings adopted where prompt.md leaves a contract open:
 * - "alike" components means exactly the same type (2 runes + 1 moonstone => no block).
 * - A block is exactly 3 alike components; 4 and 7 runes form no block.
 * - First-insurance surcharge applies to every quote, regardless of customer history.
 * - Rejections: the domain layer throws an Error; src/cli.ts maps that to a
 *   non-zero exit status plus a stderr description. The spec defines no message
 *   text, so tests assert only that an Error is thrown.
 */

describe("quote -- base premiums per item", () => {
  it("empty item list -- premium 5 G (processing fee only)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [], 0)).toBe(5);
  });
  it.todo("single sword -- base premium 100 G");
  it.todo("single amulet -- base premium 60 G");
  it.todo("single staff -- base premium 80 G");
  it.todo("single potion -- base premium 40 G");
  it.todo("single rune (component) -- base premium 25 G");
  it.todo("single moonstone (component) -- base premium 25 G");
  it.todo("unknown item type (broomstick) -- throws Error");
});

describe("quote -- component blocks of 3 alike", () => {
  it.todo("2 runes -- base premium 50 G (no block)");
  it.todo("3 runes -- base premium 60 G (block applies)");
  it.todo("4 runes -- base premium 100 G (no block: block requires exactly 3)");
  it.todo("7 runes -- base premium 175 G (no block)");
  it.todo("2 runes + 1 moonstone -- base premium 75 G (no block: different types)");
  it.todo("3 runes + 3 moonstones -- base premium 120 G (two separate blocks)");
});

describe("quote -- item-specific modifiers", () => {
  it.todo("cursed sword -- 50 % surcharge on that item's base premium");
  it.todo("sword with enchantment 5 -- 30 % high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 -- no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 -- both surcharges apply");
  it.todo(
    "cursed sword + plain amulet -- curse adds 50 G (50 % of the sword only), 210 G before further modifiers and fee",
  );
});

describe("quote -- policy-wide modifiers", () => {
  it.todo("customer with exactly 2 years -- 20 % loyalty discount applies");
  it.todo("customer with 1 year -- no loyalty discount");
  it.todo("first quote in scenario -- 10 % first-insurance surcharge applies");
  it.todo("second quote in scenario -- 15 % follow-up contract discount applies");
  it.todo("first-insurance surcharge still applies on a follow-up contract");
  it.todo("processing fee of 5 G is added at the very end");
});

describe("quote -- rounding in MHPCO's favor", () => {
  it.todo("premium of 197.5 G -- rounded up to 198 G");
  it.todo("intermediate amounts kept as fractions; only final premium rounded");
});

describe("quote -- integration examples", () => {
  it.todo("newcomer with a cursed sword -- premium 165 G");
  it.todo("long-standing customer's second contract, cursed sword ench. 7 -- premium 160 G");
});

describe("claim -- standard reimbursement", () => {
  it.todo("regular sword (steel, ench. 3), damage 500 G -- payout 400 G");
  it.todo("rune (value 250 G), damage 200 G -- payout 100 G (no special clause)");
  it.todo("deductible of 100 G applies once per damaged item");
  it.todo("dragon attack damages sword (500 G) and amulet (300 G) -- payout 600 G");
});

describe("claim -- special clauses", () => {
  it.todo("steel sword, enchantment 9, damage 1000 G -- payout 400 G (50 % then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G -- payout 700 G (full, then deductible)");
  it.todo("dragon-material sword, enchantment 8, damage 1000 G -- payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G -- payout 400 G (50 % rule wins)");
});

describe("claim -- insurance sum and cap", () => {
  it.todo("sword + amulet -- insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword -- cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("sword + 3 runes -- insurance sum 1750 G (block discount affects premium only)");
  it.todo("two swords -- insurance sum 2000 G, cap 4000 G");
  it.todo("sword, two claims of 1500 G -- first payout 1400 G, remaining cap 600 G");
  it.todo("sword, two claims of 1500 G -- second payout 600 G, remaining cap 0 G");
});

describe("claim -- multiple items of the same type", () => {
  it.todo("two sword damage entries against two insured swords -- each has its own deductible");
  it.todo("more damage entries of a type than insured -- throws Error");
});

describe("claim -- rounding and rejections", () => {
  it.todo("payout of 350.5 G -- rounded down to 350 G");
  it.todo("damage to an item not part of the policy -- throws Error");
  it.todo("damage entry with an unknown item type -- throws Error");
  it.todo("damage entry with amount -200 -- throws Error");
});

describe("cli -- scenario processing", () => {
  it.todo("processes steps sequentially and returns one result per step");
  it.todo("claim step refers to the policy created by an earlier quote via step index");
  it.todo("schema example scenario -- quote result then claim result");
  it.todo("invalid scenario -- exits non-zero and writes an error description to stderr");
});

