export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

export function quote(customer: Customer, items: Item[], contractIndex: number): number {
  const policyBasePremium = items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0);
  const firstInsurance = policyBasePremium * FIRST_INSURANCE_SURCHARGE;
  return policyBasePremium + firstInsurance + PROCESSING_FEE;
}

